CREATE     PROCEDURE [synapse_fo].[usp_Insert_GENERALJOURNALENTRY]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:50
	Description: Insert stored procedure for GENERALJOURNALENTRY from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[GENERALJOURNALENTRY]
	(
		[ACCOUNTINGDATE],
		[ACKNOWLEDGEMENTDATE],
		[BUDGETSOURCELEDGERENTRYPOSTED],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CREATEDTRANSACTIONID],
		[DataLakeModified_DateTime],
		[DOCUMENTDATE],
		[DOCUMENTNUMBER],
		--[FileName],
		[FISCALCALENDARPERIOD],
		[FISCALCALENDARYEAR],
		[JOURNALCATEGORY],
		[JOURNALNUMBER],
		[LastProcessedChange_DateTime],
		[LEDGER],
		[LEDGERENTRYJOURNAL],
		[LEDGERPOSTINGJOURNAL],
		[LEDGERPOSTINGJOURNALDATAAREAID],
		--[LSN],
		[PARTITION],
		[POSTINGLAYER],
		[RECID],
		[RECVERSION],
		--[SKS_EFTAP_ORIGPAYMVOUCH],
		[SUBLEDGERVOUCHER],
		[SUBLEDGERVOUCHERDATAAREAID],
		--[SysRowId],
		[TRANSFERID]
	)
	SELECT 
		stg.[ACCOUNTINGDATE],
		stg.[ACKNOWLEDGEMENTDATE],
		stg.[BUDGETSOURCELEDGERENTRYPOSTED],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CREATEDTRANSACTIONID],
		stg.[DataLakeModified_DateTime],
		stg.[DOCUMENTDATE],
		stg.[DOCUMENTNUMBER],
		--stg.--[FileName],
		stg.[FISCALCALENDARPERIOD],
		stg.[FISCALCALENDARYEAR],
		stg.[JOURNALCATEGORY],
		stg.[JOURNALNUMBER],
		stg.[LastProcessedChange_DateTime],
		stg.[LEDGER],
		stg.[LEDGERENTRYJOURNAL],
		stg.[LEDGERPOSTINGJOURNAL],
		stg.[LEDGERPOSTINGJOURNALDATAAREAID],
		--stg.--[LSN],
		stg.[PARTITION],
		stg.[POSTINGLAYER],
		stg.[RECID],
		stg.[RECVERSION],
		--stg.[SKS_EFTAP_ORIGPAYMVOUCH],
		stg.[SUBLEDGERVOUCHER],
		stg.[SUBLEDGERVOUCHERDATAAREAID],
		--stg.--[SysRowId],
		stg.[TRANSFERID]	
	FROM [staging_fo].[GENERALJOURNALENTRY] stg
		LEFT JOIN [synapse_fo].[GENERALJOURNALENTRY] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
